window.SDM13_SEARCH = [{"module":"m1","moduleTitle":"تطوير الذات","number":1,"title":"اكتشاف الذات ونقاط القوة والضعف","duration":"50 دقيقة","intro":"كل خطة تطوير شخصي تبدأ من سؤال بسيط: من أنا الآن؟ لا من أتمنى أن أكون فقط. اكتشاف الذات ليس جلسة تأمل عاطفية، بل عملية جمع أدلة عن قيمك واهتماماتك وقدراتك وسلوكك اليومي، ثم تحويل هذه الأدلة إلى قرارات عملية. عندما تعرف ما تجيده فعلًا وما يحتاج إلى تطوير، تتوقف عن تقليد مسارات الآخرين وتبدأ ببناء مسار يناسبك.","terms":["الوعي الذاتي","نافذة جوهري","التحليل الرباعي الشخصي"],"url":"lessons/module-01/lesson-01.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":2,"title":"تحديد الأهداف والرؤية المستقبلية","duration":"55 دقيقة","intro":"الرؤية هي الصورة الكبيرة التي تريد أن تصل إليها بعد سنوات، والهدف هو محطة محددة على الطريق. كثير من الناس يملكون أمنيات واسعة مثل «أريد أن أنجح»، لكنهم لا يملكون صياغة قابلة للتنفيذ. في هذا الدرس ستتعلم كيف تحوّل الرغبات إلى أهداف واضحة، وكيف تختبر واقعيتها قبل أن تستهلك وقتك في تنفيذها.","terms":["الرؤية","هدف SMART","التخطيط العكسي"],"url":"lessons/module-01/lesson-02.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":3,"title":"بناء عقلية النمو (Growth Mindset)","duration":"50 دقيقة","intro":"عقلية النمو ليست شعارًا تحفيزيًا ولا إنكارًا للصعوبات. هي طريقة في تفسير الفشل والتحدي: بدل أن تقول «لا أستطيع»، تسأل «ما الذي لم أتعلمه بعد، وما الاستراتيجية التالية؟». هذا الفرق الصغير في اللغة يغيّر طريقة تعاملك مع التدريب والتغذية الراجعة والانتكاسات، ويجعل التعلم استثمارًا طويل المدى بدل اختبار للذكاء.","terms":["عقلية النمو","التغذية الراجعة","منطقة الراحة"],"url":"lessons/module-01/lesson-03.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":4,"title":"إدارة الوقت وتنظيم الأولويات","duration":"55 دقيقة","intro":"إدارة الوقت ليست ملء كل ساعة بمهمة، بل اختيار ما يستحق وقتك ثم حمايته. معظم الناس لا يعانون من نقص الوقت بقدر ما يعانون من غياب الأولويات وضياع الطاقة في مهام صغيرة ومقاطعات متكررة. في هذا الدرس ستقيس أين يذهب وقتك، وترتب أولوياتك بأداة عملية، وتبني نظامًا أسبوعيًا بسيطًا يمكن الالتزام به.","terms":["العمل العميق","مصفوفة أيزنهاور","تخصيص الوقت"],"url":"lessons/module-01/lesson-04.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":5,"title":"الانضباط والتحفيز والاستمرارية","duration":"50 دقيقة","intro":"التحفيز شعور يأتي ويذهب، أما الانضباط فهو نظام يعمل حتى عندما لا تشعر بالحماس. كثير من المشاريع لا تفشل بسبب ضعف الفكرة، بل بسبب التوقف بعد أسبوعين. في هذا الدرس ستتعلم كيف تبني عادات صغيرة مقاومة للانتكاسات، وكيف تصمم بيئتك ونظام مساءلتك بحيث يصبح الاستمرار هو الخيار الأسهل.","terms":["العادة","الاحتكاك","المساءلة"],"url":"lessons/module-01/lesson-05.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":6,"title":"مهارات التواصل والثقة بالنفس","duration":"55 دقيقة","intro":"التواصل الفعال ليس امتلاك لسان طلق، بل القدرة على إيصال فكرة واضحة وفهم الطرف الآخر وبناء علاقة عمل. والثقة بالنفس ليست صوتًا عاليًا أو انعدام خوف، بل استعداد للتصرف رغم التوتر بناءً على تحضير وخبرة متراكمة. في هذا الدرس ستتعلم أدوات عملية للتحدث والاستماع والتفاوض وتقديم نفسك دون مبالغة أو تقليل.","terms":["الاستماع النشط","الحزم","التغذية الراجعة"],"url":"lessons/module-01/lesson-06.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":7,"title":"التفكير الإبداعي وحل المشكلات","duration":"55 دقيقة","intro":"الإبداع ليس موهبة غامضة يحصل عليها بعض الناس، بل عملية يمكن تدريبها: فهم المشكلة، توليد خيارات متعددة، ثم اختيار الحل واختباره. وحل المشكلات الجيد يبدأ من تعريف دقيق للمشكلة، لا من أول حل يخطر في البال. في هذا الدرس ستتعلم أدوات لإنتاج أفكار أكثر ولاختيار أفضل خيار بدل الاكتفاء بالحدس.","terms":["السبب الجذري","SCAMPER","النموذج الأولي"],"url":"lessons/module-01/lesson-07.html"},{"module":"m1","moduleTitle":"تطوير الذات","number":8,"title":"التخطيط للمستقبل المهني","duration":"60 دقيقة","intro":"التخطيط المهني ليس قرارًا واحدًا يتخذ مرة واحدة، بل سلسلة تجارب واختيارات تُراجع مع الوقت. سوق العمل الرقمي يتغير بسرعة، لكن المبادئ ثابتة: اعرف قيمة ما تقدمه، وابنِ دليلًا على مهاراتك، واختبر المسارات قبل الاستثمار الكامل فيها. في هذا الدرس ستحوّل ما تعلمته في المسار إلى خطة مهنية من 12 شهرًا، مع ملف تعريفي ومحفظة أعمال وخطوات تواصل واقعية.","terms":["فجوة المهارات","المحفظة","التواصل المهني"],"url":"lessons/module-01/lesson-08.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":1,"title":"مقدمة في التسويق الرقمي","duration":"45 دقيقة","intro":"التسويق الرقمي هو استخدام القنوات والأدوات الرقمية لفهم الجمهور وبناء علاقة معه وتقديم قيمة تحوّل الاهتمام إلى قرار. ليس مجرد إعلانات على فيسبوك أو منشورات جميلة، بل نظام يبدأ من السوق وينتهي بالقياس. في هذا الدرس ستبني صورة كاملة عن المجال: القنوات، مراحل رحلة العميل، أنواع الوسائط، والمهارات التي تحتاجها للبدء.","terms":["رحلة العميل","الوسائط المملوكة","الوسائط المدفوعة"],"url":"lessons/module-02/lesson-01.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":2,"title":"الفرق بين التسويق والبيع","duration":"45 دقيقة","intro":"كثير من المشاريع الصغيرة تخلط بين التسويق والبيع، فتطلب من الجمهور الشراء قبل أن يثق، أو تظن أن البيع الجيد يعوّض غياب الفهم للسوق. التسويق يهيئ الظروف التي يصبح فيها الشراء قرارًا منطقيًا، والبيع يدير اللحظة التي يتحول فيها الاهتمام إلى قرار. فهم الفرق يجعلك تختار الرسالة والقناة المناسبة لكل مرحلة.","terms":["عرض القيمة","معدل التحويل","البيع الاستشاري"],"url":"lessons/module-02/lesson-02.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":3,"title":"أساسيات التسويق والاستراتيجية","duration":"55 دقيقة","intro":"الاستراتيجية التسويقية هي جملة الاختيارات التي تحدد لمن تبيع، وماذا تقدم، وكيف تتميز، وأين تظهر، وكيف تقيس. بدونها تصبح الأنشطة اليومية ردود فعل على ما يفعله المنافسون. في هذا الدرس ستتعلم المزيج التسويقي، والتموضع، وخطة تسويق بسيطة يمكن تنفيذها بمشروع صغير.","terms":["المزيج التسويقي","التموضع","الاستهداف"],"url":"lessons/module-02/lesson-03.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":4,"title":"دراسة السوق والمنافسين","duration":"55 دقيقة","intro":"دراسة السوق ليست تقريرًا أكاديميًا طويلًا، بل طريقة لتقليل المخاطر قبل إنفاق الوقت والمال. تريد أن تعرف: هل توجد حاجة حقيقية؟ من يدفع؟ كم يدفع؟ من ينافسك؟ وما الفراغ الذي يمكنك ملؤه؟ في هذا الدرس ستتعلم جمع البيانات من مصادر أولية وثانوية، وبناء شبكة منافسين، واستخلاص قرار عملي.","terms":["البحث الأولي","البحث الثانوي","المنافس غير المباشر"],"url":"lessons/module-02/lesson-04.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":5,"title":"تحديد الجمهور المستهدف","duration":"50 دقيقة","intro":"«الجميع» ليس جمهورًا. عندما تحاول إرضاء كل الناس، تصبح رسالتك عامة ولا تقنع أحدًا. تحديد الجمهور المستهدف لا يعني تجاهل الآخرين، بل اختيار من تخدمه أولًا وتبني له رسالة وتجربة مناسبة. في هذا الدرس ستتعلم كيف تقسم السوق، وتبني شخصية عميل مبنية على بيانات، وتحوّلها إلى رسائل وقنوات.","terms":["التقسيم","شخصية العميل","رسالة القيمة"],"url":"lessons/module-02/lesson-05.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":6,"title":"بناء العلامة التجارية (Branding)","duration":"50 دقيقة","intro":"العلامة التجارية ليست الشعار ولا الألوان فقط. هي الوعد الذي تقدمه، والشعور الذي يبقى عند الناس بعد تعاملهم معك، وطريقة اتخاذك للقرارات. مشروع صغير يمكنه بناء علامة قوية بدون ميزانية كبيرة إذا كان متسقًا وواضحًا. في هذا الدرس ستبني أساس علامتك: الوعد، الشخصية، الصوت، والاتساق البصري.","terms":["العلامة التجارية","الهوية البصرية","صوت العلامة"],"url":"lessons/module-02/lesson-06.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":7,"title":"صناعة المحتوى (Content Marketing)","duration":"55 دقيقة","intro":"المحتوى هو الطريقة التي تثبت بها أنك تفهم جمهورك قبل أن تطلب منه الشراء. لكن النشر اليومي بلا خطة يستهلك الوقت ولا يبني شيئًا. في هذا الدرس ستتعلم كيف تختار محاور المحتوى، وتكتب منشورًا يوقف التمرير، وتبني تقويمًا واقعيًا، وتعيد استخدام المحتوى بدل إنتاج كل شيء من الصفر.","terms":["محور المحتوى","الخطاف","إعادة الاستخدام"],"url":"lessons/module-02/lesson-07.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":8,"title":"التسويق عبر مواقع التواصل الاجتماعي","duration":"55 دقيقة","intro":"وسائل التواصل ليست لوحة إعلانات، بل مساحة لبناء علاقة ومجتمع حول اهتمام مشترك. لكن كل منصة لها منطق مختلف: ما ينجح في لينكدإن لا ينجح في تيك توك. في هذا الدرس ستتعلم كيف تختار المنصات، وتبني مزيج محتوى متوازنًا، وتدير المجتمع، وتقيس النتائج دون أن تصبح أسيرًا للأرقام.","terms":["المحتوى العضوي","الوصول","UTM"],"url":"lessons/module-02/lesson-08.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":9,"title":"التسويق عبر Facebook وInstagram","duration":"60 دقيقة","intro":"فيسبوك وإنستغرام من أكثر المنصات استخدامًا في المغرب للمشاريع المحلية. لكن وجود صفحة لا يعني وجود تسويق. الفرق يصنعه وضوح الهدف، وجودة المحتوى، وإدارة الرسائل، وفهم أدوات الأعمال. في هذا الدرس ستتعلم كيف تبني حضورًا عمليًا على المنصتين، وتقرأ النتائج، وتتجنب الأخطاء الشائعة.","terms":["Meta Business Suite","الريلز","الجمهور المخصص"],"url":"lessons/module-02/lesson-09.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":10,"title":"التسويق عبر TikTok","duration":"50 دقيقة","intro":"تيك توك مختلف عن المنصات الأخرى: الاكتشاف يعتمد على جودة المحتوى وسلوك المشاهدة أكثر من عدد المتابعين. هذا يمنح المشاريع الصغيرة فرصة وصول كبيرة، لكنه يفرض أسلوبًا مختلفًا: فيديو قصير، بداية سريعة، قيمة واضحة، وإنسانية بدل الإعلان المصقول. في هذا الدرس ستتعلم كيف تبني استراتيجية تيك توك واقعية دون مطاردة الترندات فقط.","terms":["نسبة الإكمال","الخطاف البصري","الوصول البارد"],"url":"lessons/module-02/lesson-10.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":11,"title":"الإعلانات الرقمية (Paid Advertising)","duration":"60 دقيقة","intro":"الإعلان المدفوع يشتري انتباهًا، لكنه لا يشتري ثقة. عندما يكون العرض واضحًا والصفحة جاهزة، تصبح الإعلانات مسرّعًا للنمو. وعندما تكون الرسالة غامضة أو تجربة الشراء ضعيفة، تصبح مصروفًا بلا نتيجة. في هذا الدرس ستتعلم هيكل الحملة، واختيار الهدف والجمهور، وكتابة الإعلان، وقياس التكلفة والعائد.","terms":["تكلفة الاكتساب","العائد على الإنفاق الإعلاني","الجمهور المخصص"],"url":"lessons/module-02/lesson-11.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":12,"title":"أساسيات SEO","duration":"60 دقيقة","intro":"SEO هو تحسين موقعك ليظهر في نتائج البحث عندما يبحث شخص عن حل لمشكلته. هو قناة تراكمية: النتائج تتباطأ في البداية، لكن الزيارات المستمرة قد تصبح أصلًا طويل المدى. في هذا الدرس ستتعلم كيف يعمل البحث، وكيف تختار الكلمات، وتحسّن الصفحات، وتتجنب الممارسات التي تضر بموقعك.","terms":["نية البحث","الكلمة المفتاحية الطويلة","SEO المحلي"],"url":"lessons/module-02/lesson-12.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":13,"title":"تحليل البيانات وقياس النتائج","duration":"55 دقيقة","intro":"البيانات لا تتحدث من تلقاء نفسها. رقم مثل «1000 زيارة» لا يعني شيئًا دون سؤال: من أين جاءت؟ هل وجدت ما تبحث عنه؟ هل سألت أو اشترت؟ تحليل البيانات هو ربط الأرقام بهدف وقرار. في هذا الدرس ستتعلم اختيار المؤشرات، وبناء لوحة بسيطة، وتفسير النتائج دون الانخداع بالضجيج.","terms":["مؤشر الغرور","معدل التحويل","اختبار A/B"],"url":"lessons/module-02/lesson-13.html"},{"module":"m2","moduleTitle":"التسويق الرقمي","number":14,"title":"Google Analytics وGoogle Search Console","duration":"60 دقيقة","intro":"Google Analytics وSearch Console أداتان مختلفتان: الأولى تقيس ما يحدث داخل موقعك بعد الزيارة، والثانية تخبرك كيف يظهر موقعك في بحث Google. الاثنتان لا تصنعان النجاح وحدهما، لكنهما تمنحانك معلومات لا يمكن رؤيتها بالحدس. في هذا الدرس ستتعلم الإعداد الأساسي، والتقارير المهمة، وكيف تحوّل القراءة إلى قرار.","terms":["الحدث","التحويل","الفهرسة"],"url":"lessons/module-02/lesson-14.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":1,"title":"مقدمة في التجارة الإلكترونية","duration":"45 دقيقة","intro":"التجارة الإلكترونية هي بيع أو شراء المنتجات والخدمات عبر الإنترنت، لكنها أوسع من متجر إلكتروني. تشمل العرض، والدفع، والتوصيل، وخدمة العملاء، وإدارة المخزون، والتسويق. فهم النظام كاملًا قبل بناء المتجر يمنعك من إنفاق الوقت على واجهة جميلة لا تستطيع الوفاء بوعودها. في هذا الدرس ستبني صورة واضحة عن المجال وفرصه وتحدياته في السياق المغربي.","terms":["التجارة الإلكترونية","سلسلة القيمة","الدفع عند الاستلام"],"url":"lessons/module-03/lesson-01.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":2,"title":"أنواع نماذج التجارة الإلكترونية","duration":"50 دقيقة","intro":"ليس كل مشروع إلكتروني متجرًا للمنتجات. هناك نماذج متعددة، لكل منها تكاليف ومخاطر ومهارات مختلفة. اختيار النموذج الخاطئ قد يستهلك رأس المال في المخزون بينما كنت تحتاج إلى خدمة أو عمولة. في هذا الدرس ستتعرف على النماذج الرئيسية، وكيف تختار بينها بناءً على مواردك وقدرتك على الوفاء بالوعد.","terms":["D2C","الدروبشيبينغ","التسويق بالعمولة"],"url":"lessons/module-03/lesson-02.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":3,"title":"اختيار المنتجات المناسبة","duration":"55 دقيقة","intro":"اختيار المنتج هو أحد أهم قرارات المتجر. المنتج الخاطئ لا ينقذه تسويق ولا تصميم. المنتج المناسب يجمع بين طلب حقيقي، وهامش يغطي التكاليف، وقدرة على التوصيل بجودة، وقصة يمكن للعلامة أن ترويها. في هذا الدرس ستتعلم معايير الاختيار، وكيف تختبر المنتج قبل شراء مخزون كبير.","terms":["هامش المساهمة","المنتج المقلد","اختبار الطلب"],"url":"lessons/module-03/lesson-03.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":4,"title":"دراسة السوق والطلب","duration":"55 دقيقة","intro":"قبل شراء المخزون، تحتاج إلى إشارات على وجود طلب. دراسة السوق والطلب لا تعني الوصول إلى رقم دقيق، بل تقليل عدم اليقين بما يكفي لاتخاذ قرار. في هذا الدرس ستتعلم كيف تجمع إشارات الطلب من البحث والمنصات والمقابلات، وكيف تقيس الموسمية والمنافسة، وكيف تصمم اختبارًا حقيقيًا قبل الاستثمار.","terms":["إشارة الطلب","الموسمية","الطلب المسبق"],"url":"lessons/module-03/lesson-04.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":5,"title":"تحليل المنافسين","duration":"50 دقيقة","intro":"تحليل المنافسين ليس نسخ ما يفعلونه، بل فهم السوق من خلال تجاربهم. كل منافس نجح أو فشل يترك أدلة: ما يطلبه العملاء، ما يعانون منه، وما لا يقدمه أحد. في هذا الدرس ستتعلم كيف تختار المنافسين، وتقارن عروضهم، وتقرأ المراجعات، وتحدد فرصة تمايز قابلة للإثبات.","terms":["المنافس المباشر","التمايز","تحليل تجربة الشراء"],"url":"lessons/module-03/lesson-05.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":6,"title":"إنشاء متجر إلكتروني","duration":"60 دقيقة","intro":"المتجر الإلكتروني هو نقطة الثقة والتحويل، وليس مجرد واجهة لعرض المنتجات. الزائر يحتاج أن يفهم بسرعة ماذا تبيع، ولمن، وبكم، وكيف يشتري، وماذا يحدث بعد الطلب. في هذا الدرس ستتعلم كيف تختار المنصة، وتبني هيكلًا واضحًا، وتجهز الصفحات الأساسية وتجربة الهاتف قبل الإطلاق.","terms":["صفحة الهبوط","تجربة المستخدم","سياسة الإرجاع"],"url":"lessons/module-03/lesson-06.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":7,"title":"إضافة المنتجات وتنظيم المتجر","duration":"55 دقيقة","intro":"تنظيم المتجر يؤثر في قرار الشراء أكثر مما يتوقع كثيرون. الزائر الذي لا يجد ما يبحث عنه بسرعة يغادر، والمنتج الذي لا تظهر تفاصيله بوضوح يثير الأسئلة. في هذا الدرس ستتعلم كيف تبني تصنيفات منطقية، وتضيف منتجات كاملة، وتدير المخزون، وتجعل البحث والتصفية أسهل.","terms":["التصنيف","الخيارات","المخزون"],"url":"lessons/module-03/lesson-07.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":8,"title":"كتابة وصف احترافي للمنتجات","duration":"50 دقيقة","intro":"وصف المنتج ليس فقرة تجميلية، بل أداة بيع وتقليل مخاطر. العميل لا يستطيع لمس المنتج أو تجربته، لذا يعتمد على الكلمات والصور ليتخيل النتيجة ويطمئن. الوصف الجيد يترجم الخصائص إلى فوائد، ويجيب عن الاعتراضات، ويجعل الخطوة التالية واضحة. في هذا الدرس ستكتب وصفًا كاملًا لمنتج حقيقي.","terms":["الخاصية","الفائدة","الاعتراض"],"url":"lessons/module-03/lesson-08.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":9,"title":"تصوير المنتجات","duration":"55 دقيقة","intro":"في المتجر الإلكتروني، الصورة هي أقرب شيء إلى لمس المنتج. صورة واضحة تبني الثقة وتقلل الأسئلة والمرتجعات، وصورة سيئة تجعل منتجًا جيدًا يبدو رخيصًا. لا تحتاج إلى استوديو احترافي لتبدأ؛ تحتاج إلى إضاءة جيدة، خلفية نظيفة، زوايا مناسبة، واتساق. في هذا الدرس ستتعلم تصوير منتجاتك بالهاتف بجودة احترافية.","terms":["الإضاءة الطبيعية","الخلفية","المقاس المرجعي"],"url":"lessons/module-03/lesson-09.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":10,"title":"استراتيجيات التسعير","duration":"55 دقيقة","intro":"السعر ليس رقمًا يوضع لمجاراة المنافس أو لإرضاء الجميع. هو قرار استراتيجي يحدد الهامش، ويوحي بقيمة المنتج، ويؤثر في نوع العملاء الذين تجذبهم. في هذا الدرس ستتعلم طرق التسعير، وكيف تحسب التكلفة والهامش، وكيف تستخدم العروض والحزم دون تدمير الربحية.","terms":["هامش الربح","نقطة التعادل","متوسط قيمة الطلب"],"url":"lessons/module-03/lesson-10.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":11,"title":"طرق الدفع والتوصيل","duration":"55 دقيقة","intro":"الدفع والتوصيل هما اللحظة التي يتحول فيها الاهتمام إلى تجربة حقيقية. إذا كانت وسيلة الدفع غير متاحة أو تكلفة الشحن غير واضحة أو موعد التسليم غامضًا، يتراجع العميل. في هذا الدرس ستتعلم الخيارات الشائعة، وكيف تصمم سياسة شحن وتوصيل تحمي الهامش وتجربة العميل، مع إدارة المرتجعات والمصالحة المالية.","terms":["الدفع عند الاستلام","بوابة الدفع","المصالحة"],"url":"lessons/module-03/lesson-11.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":12,"title":"التجارة الإلكترونية في المغرب","duration":"55 دقيقة","intro":"كل سوق له سياقه. في المغرب، الثقة والدفع عند الاستلام والتوصيل والالتزامات الإدارية تشكل تجربة التجارة الإلكترونية بقدر ما يشكلها المنتج نفسه. فهم هذا السياق يساعدك على تصميم نموذج واقعي بدل نسخ تجربة من سوق آخر. في هذا الدرس ستتعرف على الفرص والتحديات والممارسات الإدارية الأساسية، مع التأكيد على التحقق من كل معلومة قانونية من المصادر الرسمية.","terms":["المقاول الذاتي","حماية المعطيات","الفاتورة"],"url":"lessons/module-03/lesson-12.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":13,"title":"خدمة العملاء وإدارة الطلبات","duration":"55 دقيقة","intro":"الطلب ليس نهاية الرحلة، بل بداية اختبار حقيقي لعملك. بين تأكيد الطلب والتغليف والتوصيل والرد على الأسئلة ومعالجة الشكاوى، تتشكل سمعة متجرك. كثير من المتاجر تخسر عملاء ليس بسبب المنتج، بل بسبب تأخر الرد أو موعد توصيل غير واضح أو شكوى لم تُحل. في هذا الدرس ستتعلم كيف تحوّل إدارة الطلبات وخدمة العملاء إلى نظام واضح يقلل الأخطاء ويبني الثقة والولاء.","terms":["حالة الطلب","معدل الإرجاع","وقت الاستجابة"],"url":"lessons/module-03/lesson-13.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":14,"title":"استراتيجيات تطوير المبيعات","duration":"55 دقيقة","intro":"زيادة المبيعات لا تعني زيادة الإعلانات فقط. قد يخفي النمو السريع مشكلة في الهامش أو في الطاقة التشغيلية أو في جودة الخدمة. تطوير المبيعات هو عملية منظمة لرفع قيمة كل عميل وتحسين معدل التحويل وتوسيع قنوات البيع دون الإضرار بالربحية. في هذا الدرس ستتعلم كيف تحلل مسار البيع، وتختار استراتيجية مناسبة لمرحلتك، وتقيس أثر كل تغيير.","terms":["معدل التحويل","متوسط قيمة الطلب","تكلفة اكتساب العميل"],"url":"lessons/module-03/lesson-14.html"},{"module":"m3","moduleTitle":"التجارة الإلكترونية","number":15,"title":"بناء مشروع إلكتروني مستدام","duration":"60 دقيقة","intro":"المشروع المستدام ليس المشروع الذي يبيع كثيرًا في شهر واحد، بل الذي يستمر في البيع والربح دون أن ينهار صاحبه تحت الضغط. الاستدامة تعني نظام عمل واضحًا، وهامشًا صحيًا، وخدمة قابلة للتوسع، وقرارات مبنية على أرقام لا على الحماس فقط. في هذا الدرس ستجمع خيوط المسار كله لتبني خطة مشروع إلكتروني واقعية قابلة للنمو.","terms":["اقتصاديات الوحدة","النظام التشغيلي","التوسع التدريجي"],"url":"lessons/module-03/lesson-15.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":1,"title":"مقدمة في التصميم الجرافيكي","duration":"50 دقيقة","intro":"التصميم الجرافيكي هو فن وعلم استخدام العناصر البصرية لحل مشكلة تواصل. عندما ترى إعلانًا تفهمه في ثانية، أو لافتة تجد فيها المعلومة بسرعة، أو هوية تعرفها قبل قراءة الاسم، فأنت أمام تصميم أدى وظيفته. في هذا الدرس ستتعرف على مجالات التصميم، ودور المصمم، والفرق بين التصميم والفن، وكيف تبدأ أول خطوة عملية.","terms":["الموجز","الهوية البصرية","التسلسل البصري"],"url":"lessons/module-04/lesson-01.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":2,"title":"مبادئ التصميم","duration":"55 دقيقة","intro":"مبادئ التصميم هي القواعد التي تجعل العمل البصري مفهومًا ومريحًا للعين. قد تملك صورًا جميلة وخطوطًا مناسبة، لكن دون توازن وتباين ومحاذاة وتكرار ومساحة بيضاء، يبدو التصميم فوضويًا. في هذا الدرس ستتعلم المبادئ الأساسية وترى كيف تعمل معًا في تصميم واحد.","terms":["التباين","المساحة البيضاء","التسلسل البصري"],"url":"lessons/module-04/lesson-02.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":3,"title":"نظرية الألوان","duration":"55 دقيقة","intro":"اللون ليس اختيارًا عشوائيًا، بل أداة تواصل تؤثر في الانتباه والمشاعر وسهولة القراءة. اللون نفسه قد يعني شيئًا مختلفًا حسب السياق والثقافة. في هذا الدرس ستتعلم أساسيات دائرة الألوان، والفرق بين الألوان الدافئة والباردة، وكيف تبني لوحة ألوان متوازنة بتباين كافٍ للقراءة.","terms":["الألوان المتكاملة","اللوحة اللونية","التباين اللوني"],"url":"lessons/module-04/lesson-03.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":4,"title":"الخطوط والطباعة","duration":"55 دقيقة","intro":"الخط هو الصوت البصري للكلمة. الخط نفسه قد يوحي بالفخامة أو البساطة أو التقنية أو الدفء. لكن الجمال لا يكفي؛ يجب أن يكون النص مقروءًا وواضحًا ومناسبًا للسياق. في هذا الدرس ستتعلم أنواع الخطوط، والفرق بين خط العنوان وخط المتن، وكيف تبني نظامًا طباعيًا بسيطًا ومتسقًا.","terms":["الهرم الطباعي","وزن الخط","المسافة بين الأسطر"],"url":"lessons/module-04/lesson-04.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":5,"title":"التناسق والتكوين","duration":"55 دقيقة","intro":"التكوين هو طريقة ترتيب العناصر داخل المساحة. قد تكون العناصر جيدة منفردة، لكن تنظيمها هو ما يخلق الإحساس بالتوازن والوضوح. التناسق يعني أن تكون النسب والمسافات والأحجام منسجمة لا عشوائية. في هذا الدرس ستتعلم شبكات التصميم، والنسب، وكيف تبني تكوينًا يوجه العين ويمنح العمل مظهرًا مهنيًا.","terms":["الشبكة","الهوامش","التكوين غير المتماثل"],"url":"lessons/module-04/lesson-05.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":6,"title":"تصميم الشعارات","duration":"60 دقيقة","intro":"الشعار ليس مجرد صورة جميلة، بل علامة مختصرة تحمل هوية وتميزًا. الشعار الجيد يُعرف بسرعة، ويعمل بأحجام مختلفة، ويبدو واضحًا بالأبيض والأسود، ويظل مفهومًا دون شرح. في هذا الدرس ستتعلم أنواع الشعارات، ومراحل التصميم، وكيف تختبر شعارًا قبل اعتماده.","terms":["الشعار النصي","الملف المتجهي","المساحة الآمنة"],"url":"lessons/module-04/lesson-06.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":7,"title":"تصميم المنشورات الإعلانية","duration":"55 دقيقة","intro":"المنشور الإعلاني يعمل في ثوانٍ قليلة. يجب أن يجذب الانتباه، ويوضح العرض، ويجيب عن السؤال الأول، ويقود إلى إجراء. كثير من الإعلانات تفشل ليس لأنها قبيحة، بل لأنها تحاول قول كل شيء فلا تقول شيئًا. في هذا الدرس ستتعلم بناء منشور إعلاني من الرسالة إلى التصميم النهائي.","terms":["النداء إلى الإجراء","عنصر الجذب","اختبار A/B"],"url":"lessons/module-04/lesson-07.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":8,"title":"تصميم محتوى وسائل التواصل","duration":"55 دقيقة","intro":"المحتوى على وسائل التواصل ليس إعلانات متفرقة، بل سلسلة تبني معرفة وثقة. الجمهور يرى المنشورات معًا، فإذا كانت تبدو من عوالم مختلفة، يضعف التعرف على العلامة. في هذا الدرس ستتعلم بناء نظام محتوى بصري متسق، وتخطيط تقويم بسيط، وتصميم منشورات تعمل على الهاتف.","terms":["قالب المنشور","تقويم المحتوى","بنك الأفكار"],"url":"lessons/module-04/lesson-08.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":9,"title":"التصميم باستخدام Canva","duration":"50 دقيقة","intro":"Canva أداة تجعل التصميم متاحًا لمن لا يعرف البرامج المعقدة، لكنها لا تلغي الحاجة إلى المبادئ. كثير من التصاميم تبدو متشابهة لأن أصحابها يستخدمون القوالب كما هي دون تعديل. في هذا الدرس ستتعلم كيف تستخدم Canva بذكاء: تبني قالبًا خاصًا بك، تضبط الشبكة والمسافات، وتصدر الملفات بالصيغ الصحيحة.","terms":["القوالب","الهوامش والقص","التصدير"],"url":"lessons/module-04/lesson-09.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":10,"title":"تصميم الإعلانات التجارية","duration":"55 دقيقة","intro":"الإعلان التجاري ليس لوحة فنية، بل أداة لتحقيق هدف: زيادة طلب، أو تعريف بمنتج، أو إطلاق عرض. نجاحه يُقاس بالنتيجة لا بالإعجاب. في هذا الدرس ستتعلم كيف تربط التصميم بهدف تجاري، وتختار الرسالة والعرض، وتصمم إعلانًا يعمل على القنوات المختلفة.","terms":["تكلفة الطلب","نسبة التحويل","النسخة الإعلانية"],"url":"lessons/module-04/lesson-10.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":11,"title":"بناء الهوية البصرية","duration":"60 دقيقة","intro":"الهوية البصرية هي النظام الذي يجعل العلامة تُعرف قبل قراءة اسمها. الشعار جزء منها، لكنها تشمل الألوان والخطوط والصور والأيقونات والمسافات وطريقة التطبيق. بدون نظام، تتحول كل منشورات العلامة إلى اجتهادات منفصلة. في هذا الدرس ستتعلم كيف تجمع العناصر في دليل هوية بسيط وقابل للاستخدام.","terms":["دليل الهوية","نظام الألوان","التطبيق"],"url":"lessons/module-04/lesson-11.html"},{"module":"m4","moduleTitle":"التصميم الجرافيكي","number":12,"title":"بناء ملف الأعمال Portfolio","duration":"60 دقيقة","intro":"ملف الأعمال ليس ألبوم صور، بل حجة مهنية تثبت أنك تستطيع حل مشكلات تصميم. العميل أو صاحب العمل لا يريد أن يرى أنك تعرف الألوان فقط، بل كيف تفكر وتستمع وتنفذ وتتعامل مع القيود. في هذا الدرس ستتعلم كيف تختار مشاريعك، وتكتب دراسة حالة، وتعرض عملك بطريقة تجذب الفرص.","terms":["دراسة الحالة","الموجز الواقعي","ملف الأعمال"],"url":"lessons/module-04/lesson-12.html"}];
